"""
    Converts a string with the contents 'true' or 'false' to the
    appropriate boolean value.

    Examples:

    >>> stringToBool( 'true' )
    True

    >>> stringToBool( 'false' )
    False

    >>> stringToBool( 'True' )
    Traceback (most recent call last):
    ...
    ValueError: can't convert to boolean: True
    """
def stringToBool(string: Any) -> object {
    if (string == "true") {
        return True;
    } elif (string == "false") {
        return False;
    } else {
        raise ValueError(("can't convert to boolean: %s" % string));
    }
}

"""Helper function to normalize the start and end of an array by counting from the end of the array (just like Python).

    :type length: non-negative integer
    :param length: length of the array in question
    :type start: integer
    :param start: starting index to interpret
    :type end: integer
    :param end: ending index to interpret
    :rtype: (non-negative integer, non-negative integer)
    :return: (normalized starting index, normalized ending index)
    """
def startEnd(length: Any, start: Any, end: Any) -> object {
    if (start >= 0) {
        normStart = start;
    } else {
        normStart = length + start;
    }
    if (normStart < 0) {
        normStart = 0;
    }
    if (normStart > length) {
        normStart = length;
    }
    if (end >= 0) {
        normEnd = end;
    } else {
        normEnd = length + end;
    }
    if (normEnd < 0) {
        normEnd = 0;
    }
    if (normEnd > length) {
        normEnd = length;
    }
    if (normEnd < normStart) {
        normEnd = normStart;
    }
    return (normStart, normEnd);
}

